  "servers.multicore.hint": "Installiert die Mods, die zu diesem Loader und dieser Minecraft-Version passen, überspringt alles, was sich in die Quere käme, und lässt sich rückgängig machen.",
  "servers.multicore.open": "Einrichten",
  "servers.multicore.intro": "Der Spieltick von Minecraft läuft auf einem einzigen Thread, und daran ändern diese Mods nichts. Sie verlagern andere Arbeit auf deine übrigen Kerne, etwa das Aufbauen von Chunks für den Bildschirm sowie das Laden und Generieren von Chunks, und machen den Tick selbst leichter.",
