  "servers.multicore.undone": "Rückgängig gemacht. Die Mods liegen im Papierkorb.",
  "servers.multicore.reason.vanilla": "Das ist Vanilla und kann keine Mods ausführen. Mods brauchen einen Mod-Loader wie Fabric oder NeoForge. ResinCraft wandelt es nicht für dich um: Erstelle stattdessen ein neues mit Mod-Loader.",
  "servers.multicore.reason.noLoader": "Dieser Loader ist zu alt für diese Mods. Sie brauchen Fabric, Quilt, NeoForge oder Forge.",
  "servers.multicore.reason.noMods": "Keine dieser Mods hat einen Build für diesen Loader und diese Minecraft-Version, daher gibt es nichts zu installieren.",
  "servers.multicore.reason.plugins": "Plugins können den Tick nicht auf mehrere Kerne verteilen: Sie laufen im Haupt-Thread des Servers. Paper erledigt Chunk-Arbeit bereits auf anderen Kernen. Den Tick selbst auf mehreren Kernen laufen zu lassen, geht nur, wenn du die Server-Software auf Folia umstellst.",
  "servers.multicore.reason.hybrid": "Arclight mischt Mods und Plugins, und diese Mods ändern denselben Code wie Arclight. Hier sind sie nicht sicher, daher wird nichts angeboten.",
  "servers.multicore.reason.bedrock": "Bedrock-Server sind ein eigenes Programm, das keine Java-Mods oder -Plugins ausführen kann, daher gibt es nichts einzurichten.",
  "servers.multicore.reason.folia": "Dieser Server läuft mit Folia, das getrennte Regionen der Welt bereits auf getrennten Kernen tickt.",
  "servers.multicore.reason.noJavaMods": "Diese Server-Software kann keine Mods für Fabric, Quilt, NeoForge oder Forge ausführen, daher gibt es nichts einzurichten.",
  "servers.multicore.folia.title": "Zu Folia wechseln (optional)",
  "servers.multicore.folia.warning": "Folia tickt getrennte Regionen der Welt auf getrennten Kernen. Das hilft also nur, wenn die Spieler verteilt sind, und das Folia-Team empfiehlt mindestens 16 Kerne. Viele Plugins funktionieren damit nicht. Das ändert die Software des Servers, also mach es nur, wenn du deine Plugins geprüft hast.",
